#RisingUpForSIDS"}

{"@type": "WebPage", "author": {"name": "United Nations Office for Disaster Risk Reduction (UNDRR)", "image": {"url": "https://media.licdn.com/dms/image/v2/C4E0BAQExgWZfdWTDHA/company-logo_100_100/company-logo_100_100/0/1631312411178?e=2147483647&v=beta&t=LZI3il77uW1BbypOlI-rjx0RailOby1neUteSrsNLpo", "@type": "ImageObject"}, "url": "https://ch.linkedin.com/company/undrr", "@type": "Organization", "interactionStatistic": {"@type": "InteractionCounter", "interactionType": "http://schema.org/FollowAction", "userInteractionCount": 1162159}}, "headline": "Disasters don't have to happen. They are not a 'natural' part of life. ❌ 

